# aplicar-v68-suporte-com-3-abas.ps1
# Corrige a tela de suporte conforme solicitado:
#
# Remove o uso de:
# /admin/support?tab=admin-requests
#
# Agora fica tudo em:
# /admin/support
#
# Abas dentro da tela:
# 1. Suporte normal
# 2. Suporte impulsionamentos
# 3. Suporte aprovação de admins
#
# Tambem remove a rota antiga /admin/support/admin-requests.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v68-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

function Patch-HeaderSupportLinks() {
  $HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

  if (-not (Test-Path $HeaderPath)) {
    Write-Host "Aviso: CustomerHeader.tsx nao encontrado." -ForegroundColor Yellow
    return
  }

  $Content = Get-Content $HeaderPath -Raw
  $Original = $Content

  $Content = $Content.Replace('/admin/support?tab=admin-requests', '/admin/support')
  $Content = $Content.Replace('/admin/support/admin-requests', '/admin/support')

  # Remove entradas separadas que apontavam para abas antigas. Agora tudo fica no Suporte.
  $Lines = $Content -split "`r?`n"
  $Filtered = New-Object System.Collections.Generic.List[string]

  foreach ($Line in $Lines) {
    if ($Line -match 'Solicitaç|Solicitac|Impulsionamentos') {
      continue
    }

    $Filtered.Add($Line)
  }

  $Content = ($Filtered -join "`r`n")

  # Garante que exista um link claro para Suporte no menu admin/super admin.
  if ($Content -notmatch 'label:\s*"Suporte",\s*href:\s*"/admin/support"') {
    $Content = $Content.Replace(
      '{ label: "Pedidos", href: "/admin/orders" },',
      '{ label: "Pedidos", href: "/admin/orders" },' + "`r`n" + '    { label: "Suporte", href: "/admin/support" },'
    )
  }

  if ($Content -ne $Original) {
    $Backup = "$HeaderPath.bak-v68-$Stamp"
    Copy-Item $HeaderPath $Backup -Force
    Set-Content -Path $HeaderPath -Value $Content -Encoding UTF8
    Write-Host "Header atualizado: suporte agora aponta apenas para /admin/support." -ForegroundColor Green
  } else {
    Write-Host "Header sem alteracoes." -ForegroundColor Yellow
  }
}

function Remove-OldAdminRequestsRoute() {
  $OldDir = Join-Path $Root "apps\web\src\app\admin\support\admin-requests"

  if (Test-Path $OldDir) {
    $BackupDir = "$OldDir.bak-v68-$Stamp"
    Copy-Item $OldDir $BackupDir -Recurse -Force
    Remove-Item $OldDir -Recurse -Force
    Write-Host "Rota antiga removida: apps\web\src\app\admin\support\admin-requests" -ForegroundColor Green
    Write-Host "Backup da rota antiga: $BackupDir" -ForegroundColor DarkGray
  } else {
    Write-Host "Rota antiga admin-requests nao existia." -ForegroundColor Yellow
  }
}

Write-Host "Aplicando v68 - suporte com 3 abas internas..." -ForegroundColor Cyan

$SupportPageBase64 = ""

Write-TextBase64File "apps\web\src\app\admin\support\page.tsx" $SupportPageBase64
Patch-HeaderSupportLinks
Remove-OldAdminRequestsRoute

Write-Host ""
Write-Host "v68 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Agora a tela correta e apenas:" -ForegroundColor Cyan
Write-Host "/admin/support" -ForegroundColor Cyan
Write-Host ""
Write-Host "Abas:" -ForegroundColor Cyan
Write-Host "- Suporte normal" -ForegroundColor Cyan
Write-Host "- Suporte impulsionamentos" -ForegroundColor Cyan
Write-Host "- Suporte aprovacao de admins" -ForegroundColor Cyan
Write-Host ""
Write-Host "Reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
